import numpy as np, math
from collections import defaultdict, Counter

def comps(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; objs=[]
    for y in range(H):
        for x in range(W):
            if seen[y][x] or g[y][x]==9: continue
            c=g[y][x]; st=[(y,x)]; seen[y][x]=True; cl=[]
            while st:
                cy,cx=st.pop(); cl.append((cy,cx))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=cy+dy,cx+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True; st.append((ny,nx))
            objs.append((c,cl))
    return objs

def isL(cl):
    S=set(cl); ys=sorted({y for y,x in cl}); xs=sorted({x for y,x in cl})
    for (cy,cx) in cl:
        vcol=sorted(y for y,x in cl if x==cx); hrow=sorted(x for y,x in cl if y==cy)
        if len(vcol)+len(hrow)-1==len(cl) and S=={(y,cx) for y in vcol}|{(cy,x) for x in hrow}:
            if all(vcol[i+1]-vcol[i]==1 for i in range(len(vcol)-1)) and all(hrow[i+1]-hrow[i]==1 for i in range(len(hrow)-1)):
                if (cy==vcol[0] or cy==vcol[-1]) and (cx==hrow[0] or cx==hrow[-1]): return True
    return False

def skey(cl):
    ys=[y for y,x in cl]; xs=[x for y,x in cl]
    return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cl))

